  ('la-pt', 'la-t731', 'frase', 'A1', array['trecho']::text[], null, 'db08d3fc', array['Salve, Rainha, mãe das misericórdias, vida, doçura e esperança nossa, salve.', 'Salve, Rainha, mãe de misericórdia, vida, doçura e esperança minha, salve.', 'Salve, Rainha, mãe de misericórdia, vida, doçura e esperança nossa, salve.', 'Salve, Rainha, mãe de misericórdia, vida, doçura e esperança vossa, salve.', 'Salve, Rainha, mãe, a misericórdia, a vida, a doçura e a esperança nossa, salve.']::text[]),
  ('la-pt', 'la-t732', 'frase', 'A1', array['trecho']::text[], null, '98952a1a', array['A ti clamam, exilados filhos de Eva.', 'A ti clamamos, exilados filhos de Eva.', 'A ti clamo, exilado filho de Eva.', 'A ti clamávamos, exilados filhos de Eva.', 'Tu clamas a nós, exilados filhos de Eva.']::text[]),
  ('la-pt', 'la-t733', 'frase', 'A1', array['trecho']::text[], null, '504910f1', array['A ti suspiram, gemendo e chorando neste vale de lágrimas.', 'A ti suspiramos, gemendo e chorando naquele vale de lágrimas.', 'A ti suspiramos, gemendo e chorando neste vale de lágrimas.', 'A ti suspiramos, gemendo e chorando nestes vales de lágrimas.', 'A ti suspirávamos, gemendo e chorando neste vale de lágrimas.']::text[]),
  ('la-pt', 'la-t734', 'frase', 'A1', array['trecho']::text[], null, 'b4550c04', array['Eia, pois, advogada nossa, volta para eles aqueles teus olhos misericordiosos.', 'Eia, pois, advogada nossa, volta para nós aquele teu olho misericordioso.', 'Eia, pois, advogada nossa, volta para nós aqueles teus olhos misericordiosos.', 'Eia, pois, advogada nossa, voltaste para nós aqueles teus olhos misericordiosos.', 'Eia, pois, advogadas nossas, voltai para nós aqueles teus olhos misericordiosos.']::text[]),
  ('la-pt', 'la-t735', 'frase', 'A1', array['trecho']::text[], null, '1f6384d1', array['E Jesus, bendito fruto do teu ventre, mostra-lhes depois deste exílio', 'E Jesus, bendito fruto do teu ventre, mostra-nos antes deste exílio', 'E Jesus, bendito fruto do teu ventre, mostra-nos depois deste exílio', 'E Jesus, bendito fruto do teu ventre, mostrou-nos depois deste exílio', 'E Jesus, bendito fruto dos teus ventres, mostra-nos depois deste exílio']::text[]),
